exercises.solutionCode:
#include <stdint.h>
#include <stddef.h>

typedef struct {
    uint32_t last_ms;
    int      initialized;
} debounce_t;

int debounce_accept(debounce_t *st, uint32_t now_ms, uint32_t interval_ms)
{
    if (st == NULL) {
        return -1;
    }

    /* 首次调用：没有参照时刻，直接接受并建立基准 */
    if (!st->initialized) {
        st->last_ms = now_ms;
        st->initialized = 1;
        return 1;
    }

    /* interval_ms == 0：不设消抖窗口 */
    if (interval_ms == 0) {
        st->last_ms = now_ms;
        return 1;
    }

    /* 无符号减法在 32 位回绕时依然给出正确的正向间隔 */
    if ((uint32_t)(now_ms - st->last_ms) >= interval_ms) {
        st->last_ms = now_ms;
        return 1;
    }

    return 0;
}
